function maxBacktickRun(text) {
  const runs = text.match(/`+/g);
  return runs ? runs.reduce((max, run) => Math.max(max, run.length), 0) : 0;
}

function process(data) {
  const text = data && data.selection;
  if (typeof text !== 'string') {
    throw new TypeError('selection must be a string');
  }
  if (text === '') {
    return '';
  }

  const longestRun = maxBacktickRun(text);
  if (!/\r\n|\n|\r/.test(text)) {
    const fence = '`'.repeat(longestRun + 1);
    const needsPadding =
      text.startsWith('`') ||
      text.endsWith('`') ||
      (text.startsWith(' ') && text.endsWith(' ') && !/^ +$/.test(text));
    return needsPadding ? `${fence} ${text} ${fence}` : `${fence}${text}${fence}`;
  }

  const newline = text.match(/\r\n|\n|\r/)[0];
  const fence = '`'.repeat(Math.max(3, longestRun + 1));
  const separator = /(?:\r\n|\n|\r)$/.test(text) ? '' : newline;
  return `${fence}${newline}${text}${separator}${fence}`;
}
